export type CartItem = { sku: string; price: number; qty: number; taxable: boolean };

export function subtotal(items: CartItem[]): number {
  return items.reduce((s, i) => s + i.price * i.qty, 0);
}

export function total(items: CartItem[], shipping: number): number {
  return subtotal(items) + shipping;
}

